@section('scripts')<script>document.querySelectorAll('[data-copy-target]').forEach(button => button.addEventListener('click', async () => { const input = document.getElementById(button.dataset.copyTarget); try { await navigator.clipboard.writeText(input.value); button.textContent = 'Copied'; setTimeout(() => button.textContent = 'Copy link', 2000); } catch { input.classList.remove('pm-sr-only'); input.select(); button.textContent = 'Select and copy'; } })); const inviteDepartment = document.getElementById('pm-invite-department'); const invitePosition = document.getElementById('pm-invite-position'); if (inviteDepartment && invitePosition) { const update = () => { for (const option of invitePosition.options) { if (!option.value) continue; option.hidden = option.dataset.department !== inviteDepartment.value; option.disabled = option.hidden; } if (invitePosition.selectedOptions[0]?.disabled) invitePosition.value = ''; }; inviteDepartment.addEventListener('change', update); update(); }const batchDepartment=document.querySelector('[data-batch-department]'); const batchPosition=document.querySelector('[data-batch-position]'); if(batchDepartment&&batchPosition){const refresh=()=>{for(const option of batchPosition.options){if(!option.value)continue;option.hidden=option.dataset.department!==batchDepartment.value;option.disabled=option.hidden;}if(batchPosition.selectedOptions[0]?.disabled)batchPosition.value='';};batchDepartment.addEventListener('change',refresh);refresh();}</script>@endsection
